CREATE TABLE "customers" (
  "customer_id" INTEGER PRIMARY KEY,
  "email_address" VARCHAR(255) NOT NULL,
  "full_name" VARCHAR(255) NOT NULL
);

CREATE TABLE "products" (
  "product_id" INTEGER PRIMARY KEY,
  "product_name" VARCHAR(255) NOT NULL,
  "unit_price" DECIMAL(10,2),
  "product_details" TEXT,
  "product_image" BLOB,
  "image_mime_type" VARCHAR(512),
  "image_filename" VARCHAR(512),
  "image_charset" VARCHAR(512),
  "image_last_updated" DATETIME
);

CREATE TABLE "stores" (
  "store_id" INTEGER PRIMARY KEY,
  "store_name" VARCHAR(255) NOT NULL,
  "web_address" VARCHAR(100),
  "physical_address" VARCHAR(512),
  "latitude" DECIMAL(9,6),
  "longitude" DECIMAL(9,6),
  "logo" BLOB,
  "logo_mime_type" VARCHAR(512),
  "logo_filename" VARCHAR(512),
  "logo_charset" VARCHAR(512),
  "logo_last_updated" DATETIME,
  CONSTRAINT "store_at_least_one_address_c" CHECK ((("web_address" is not null) or ("physical_address" is not null)))
);

CREATE TABLE "inventory" (
  "inventory_id" INTEGER PRIMARY KEY,
  "store_id" INTEGER NOT NULL,
  "product_id" INTEGER NOT NULL,
  "product_inventory" INTEGER NOT NULL,
  CONSTRAINT "inventory_product_id_fk" FOREIGN KEY ("product_id") REFERENCES "products" ("product_id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "inventory_store_id_fk" FOREIGN KEY ("store_id") REFERENCES "stores" ("store_id") ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE "orders" (
  "order_id" INTEGER PRIMARY KEY,
  "order_tms" DATETIME NOT NULL,
  "customer_id" INTEGER NOT NULL,
  "order_status" VARCHAR(10) NOT NULL,
  "store_id" INTEGER NOT NULL,
  CONSTRAINT "orders_customer_id_fk" FOREIGN KEY ("customer_id") REFERENCES "customers" ("customer_id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "orders_store_id_fk" FOREIGN KEY ("store_id") REFERENCES "stores" ("store_id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "orders_status_c" CHECK (("order_status" in ('CANCELLED','COMPLETE','OPEN','PAID','REFUNDED','SHIPPED')))
);

CREATE TABLE "shipments" (
  "shipment_id" INTEGER PRIMARY KEY,
  "store_id" INTEGER NOT NULL,
  "customer_id" INTEGER NOT NULL,
  "delivery_address" VARCHAR(512) NOT NULL,
  "shipment_status" VARCHAR(100) NOT NULL,
  CONSTRAINT "shipments_customer_id_fk" FOREIGN KEY ("customer_id") REFERENCES "customers" ("customer_id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "shipments_store_id_fk" FOREIGN KEY ("store_id") REFERENCES "stores" ("store_id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "shipment_status_c" CHECK (("shipment_status" in ('CREATED','SHIPPED','IN-TRANSIT','DELIVERED')))
);

CREATE TABLE "order_items" (
  "order_id" INTEGER NOT NULL,
  "line_item_id" INTEGER NOT NULL,
  "product_id" INTEGER NOT NULL,
  "unit_price" DECIMAL(10,2) NOT NULL,
  "quantity" INTEGER NOT NULL,
  "shipment_id" INTEGER,
  PRIMARY KEY ("order_id", "line_item_id"),
  CONSTRAINT "order_items_order_id_fk" FOREIGN KEY ("order_id") REFERENCES "orders" ("order_id") ON UPDATE NO ACTION ON DELETE NO ACTION,
